<?php /** 赛事业务视图；负责人：王乐之（2411302）；AI辅助开发。 */ use yii\helpers\Html;$this->title=$match->homeTeam->name.' vs '.$match->awayTeam->name;?><h1><?= Html::encode($this->title) ?></h1><p><?= Html::encode($match->stage->name) ?> · <?= Html::encode((new DateTimeImmutable($match->kicks_off_at,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Shanghai'))->format('Y-m-d H:i')) ?> 北京时间 · <?= Html::encode($match->stadium->name) ?></p><div class="wc-score"><?= (int)$match->normal_home+(int)$match->extra_home ?> : <?= (int)$match->normal_away+(int)$match->extra_away ?></div><p>常规时间 <?= $match->normal_home ?>:<?= $match->normal_away ?>；加时 <?= $match->extra_home??0 ?>:<?= $match->extra_away??0 ?><?php if($match->penalty_home!==null):?>；点球大战 <?= $match->penalty_home ?>:<?= $match->penalty_away ?><?php endif ?></p><?php if(!Yii::$app->user->isGuest):?><?= Html::beginForm(['favorite/toggle','type'=>'match','id'=>$match->id],'post') ?><button>收藏 / 取消收藏比赛</button><?= Html::endForm() ?><?php endif ?><h2>比赛事件</h2><table><tr><th>时间</th><th>球队</th><th>球员</th><th>事件</th></tr><?php foreach($match->events as $e):?><tr><td><?= $e->minute ?><?= $e->added_minute?'+'.$e->added_minute:'' ?>′</td><td><?= Html::encode($e->team->name) ?></td><td><?= Html::encode($e->player->name??'待核对') ?></td><td><?= Html::encode(['goal'=>'进球','penalty_goal'=>'比赛内点球进球','own_goal'=>'乌龙球','yellow_card'=>'黄牌','red_card'=>'红牌','shootout_goal'=>'点球大战命中','shootout_miss'=>'点球大战未中'][$e->type]??$e->type) ?></td></tr><?php endforeach ?></table>